function top(map, n) { return Object.keys(map).map(function (k) { return [k, map[k]]; }).sort(function (a, b) { return b[1] - a[1]; }).slice(0, n); }
function pc(a, b) { return b ? Math.round(a / b * 1000) / 10 + '%' : '-'; }
var end = new Date(); end.setUTCHours(0, 0, 0, 0);
var start = new Date(end.getTime() - 86400000);
function cfVal(t, id) {
  var f = (t.custom_fields || []).filter(function (x) { return Number(x.id) === Number(id); })[0];
  if (!f || f.value === null || f.value === undefined || f.value === '' || f.value === false) return null;
  return String(f.value);
}
function analyse(brand, ticketsNode, fieldsNode) {
  var tj = $(ticketsNode).first().json || {};
  var tickets = (tj.results || []).filter(function (t) { return t && t.id; });
  var fields = (($(fieldsNode).first().json || {}).ticket_fields) || [];
  var cat = fields.filter(function (f) { return /categor/i.test(String(f.title || '')) && f.active && f.type === 'tagger'; })[0];
  var langFields = fields.filter(function (f) { return /lang/i.test(String(f.title || '')); });
  var res = {
    brand: brand,
    window_utc: start.toISOString().slice(0, 16) + ' to ' + end.toISOString().slice(0, 16),
    sampled: tickets.length,
    more_than_one_page: !!(tj.meta && tj.meta.has_more),
    tickets_carry_custom_fields: tickets.filter(function (t) { return Array.isArray(t.custom_fields) && t.custom_fields.length; }).length,
    fetch_error: tj.error ? String(JSON.stringify(tj.error)).slice(0, 200) : '',
    category_field_for_gap_analysis: cat ? cat.id + ': ' + cat.title : 'none found',
    language_fields: []
  };
  langFields.forEach(function (f) {
    var names = {};
    (f.custom_field_options || []).forEach(function (o) { names[o.value] = o.name; });
    var set = 0, byCh = {}, byStatus = {}, values = {}, missCat = {};
    tickets.forEach(function (t) {
      var ch = (t.via && t.via.channel) || 'unknown';
      var b = byCh[ch] = byCh[ch] || { n: 0, set: 0 };
      var s = byStatus[t.status] = byStatus[t.status] || { n: 0, set: 0 };
      b.n++; s.n++;
      var v = cfVal(t, f.id);
      if (v !== null) { set++; b.set++; s.set++; values[v] = (values[v] || 0) + 1; }
      else { var c = cat ? (cfVal(t, cat.id) || '(no category)') : '(n/a)'; missCat[c] = (missCat[c] || 0) + 1; }
    });
    var chOut = {}; Object.keys(byCh).forEach(function (k) { chOut[k] = byCh[k].set + '/' + byCh[k].n + ' (' + pc(byCh[k].set, byCh[k].n) + ')'; });
    var stOut = {}; Object.keys(byStatus).forEach(function (k) { stOut[k] = byStatus[k].set + '/' + byStatus[k].n + ' (' + pc(byStatus[k].set, byStatus[k].n) + ')'; });
    res.language_fields.push({
      id: f.id, title: f.title, type: f.type, active: f.active, options: (f.custom_field_options || []).length,
      coverage: set + '/' + tickets.length + ' (' + pc(set, tickets.length) + ')',
      coverage_by_channel: chOut,
      coverage_by_status: stOut,
      distinct_values: Object.keys(values).length,
      top_values: top(values, 15).map(function (x) { return [x[0], names[x[0]] || '(not an option)', x[1]]; }),
      ambiguous_values: top(values, 100).filter(function (x) { return /other|unknown|undetermin|n\/a|none|^-$/i.test(x[0] + ' ' + (names[x[0]] || '')); }),
      missing_by_category: top(missCat, 10)
    });
  });
  return res;
}
return [
  { json: analyse('personality', 'personality tickets', 'personality fields') },
  { json: analyse('myqrcode', 'myqrcode tickets', 'myqrcode fields') }
];
